//! Checks every allocation method against independent Python reference implementations.
//!
//! The inputs live in `tests/fixtures/datasets.json` and the expected weights in
//! `tests/fixtures/expected.json`, both generated by the scripts in `reference/` (see
//! `reference/README.md`). Every case is checked and all failures are reported together.

use cutup::{
    BlackLitterman, CovarianceConfig, CutupError, EqualWeight, Herc, Hrp, InverseVariance,
    InverseVolatility, Linkage, MaxDiversification, MaxSharpe, MeanVariance, MinCvar, MinVariance,
    Returns, RiskParity, View, WeightBounds, Weights,
};
use nalgebra::DMatrix;
use serde_json::Value;

const DATASETS: &str = include_str!("fixtures/datasets.json");
const EXPECTED: &str = include_str!("fixtures/expected.json");

fn rows(rows: &Value) -> Vec<Vec<f64>> {
    rows.as_array()
        .expect("data is an array of rows")
        .iter()
        .map(floats)
        .collect()
}

fn matrix(rows: &[Vec<f64>]) -> DMatrix<f64> {
    DMatrix::from_fn(rows.len(), rows[0].len(), |i, j| rows[i][j])
}

fn floats(values: &Value) -> Vec<f64> {
    values
        .as_array()
        .expect("expected an array of numbers")
        .iter()
        .map(|v| v.as_f64().expect("expected a number"))
        .collect()
}

fn allocator(dataset: &Value) -> Returns {
    let data = rows(&dataset["data"]);
    match dataset["kind"].as_str() {
        Some("prices") => Returns::from_prices(&data),
        Some("returns") => Returns::new(&data),
        other => panic!("unknown dataset kind {other:?}"),
    }
    .expect("reference datasets are valid input")
}

/// The largest absolute return in a dataset, with prices turned into simple returns as
/// `Returns::from_prices` does.
fn returns_scale(dataset: &Value) -> f64 {
    let data = matrix(&rows(&dataset["data"]));
    let returns = match dataset["kind"].as_str() {
        Some("prices") => DMatrix::from_fn(data.nrows() - 1, data.ncols(), |t, i| {
            data[(t + 1, i)] / data[(t, i)] - 1.0
        }),
        _ => data,
    };
    returns.amax()
}

fn covariance_config(params: &Value) -> CovarianceConfig {
    let mut config = CovarianceConfig::default();
    if let Some(lambda) = params["shrinkage"].as_f64() {
        config = config.shrinkage(lambda);
    }
    if let Some(epsilon) = params["regularization"].as_f64() {
        config = config.regularization(epsilon);
    }
    config
}

/// Bounds from `bounds: [lower, upper]` for every asset, or from per-asset `lower_bounds`
/// and `upper_bounds`, if the case has either.
fn weight_bounds(params: &Value) -> Option<WeightBounds> {
    if params["bounds"].is_array() {
        let bounds = floats(&params["bounds"]);
        return Some(WeightBounds::uniform(bounds[0], bounds[1]));
    }
    params["lower_bounds"].is_array().then(|| {
        WeightBounds::per_asset(
            floats(&params["lower_bounds"]),
            floats(&params["upper_bounds"]),
        )
    })
}

fn mean_variance(params: &Value) -> MeanVariance {
    let method = match (
        params["risk_aversion"].as_f64(),
        params["target_return"].as_f64(),
    ) {
        (Some(gamma), None) => MeanVariance::risk_aversion(gamma),
        (None, Some(target)) => MeanVariance::target_return(target),
        _ => panic!("mean_variance needs exactly one of risk_aversion or target_return"),
    };
    let method = method.covariance(covariance_config(params));
    if params["expected_returns"].is_array() {
        method.expected_returns(floats(&params["expected_returns"]))
    } else {
        method
    }
}

fn max_sharpe(params: &Value) -> MaxSharpe {
    let method = MaxSharpe::default()
        .risk_free_rate(params["risk_free_rate"].as_f64().unwrap_or(0.0))
        .covariance(covariance_config(params));
    if params["expected_returns"].is_array() {
        method.expected_returns(floats(&params["expected_returns"]))
    } else {
        method
    }
}

fn risk_parity(params: &Value) -> RiskParity {
    let method = RiskParity::default().covariance(covariance_config(params));
    if params["risk_budgets"].is_array() {
        method.risk_budgets(floats(&params["risk_budgets"]))
    } else {
        method
    }
}

fn linkage(params: &Value) -> Linkage {
    match params["linkage"].as_str() {
        None | Some("single") => Linkage::Single,
        Some("complete") => Linkage::Complete,
        Some("average") => Linkage::Average,
        Some("ward") => Linkage::Ward,
        Some(other) => panic!("unknown linkage {other}"),
    }
}

fn hrp(params: &Value) -> Hrp {
    Hrp::default()
        .linkage(linkage(params))
        .covariance(covariance_config(params))
}

fn herc(params: &Value) -> Herc {
    let method = Herc::default()
        .linkage(linkage(params))
        .covariance(covariance_config(params));
    match params["clusters"].as_u64() {
        Some(k) => method.clusters(k as usize),
        None => method,
    }
}

/// The model a `black_litterman` case describes. Its expected returns are checked like
/// weights.
fn black_litterman(params: &Value) -> BlackLitterman {
    let mut model = BlackLitterman::new(
        floats(&params["market_weights"]),
        params["risk_aversion"].as_f64().unwrap(),
    )
    .risk_free_rate(params["risk_free_rate"].as_f64().unwrap_or(0.0))
    .covariance(covariance_config(params));
    if let Some(tau) = params["tau"].as_f64() {
        model = model.tau(tau);
    }
    for view in params["views"].as_array().into_iter().flatten() {
        let q = view["q"].as_f64().unwrap();
        let mut built = if let Some(asset) = view["absolute"].as_u64() {
            View::absolute(asset as usize, q)
        } else if view["relative"].is_array() {
            let pair = &view["relative"];
            View::relative(
                pair[0].as_u64().unwrap() as usize,
                pair[1].as_u64().unwrap() as usize,
                q,
            )
        } else {
            View::portfolio(floats(&view["portfolio"]), q)
        };
        match (view["variance"].as_f64(), view["confidence"].as_f64()) {
            (Some(omega), None) => built = built.variance(omega),
            (None, Some(confidence)) => built = built.confidence(confidence),
            (None, None) => {}
            (Some(_), Some(_)) => panic!("a view sets at most one of variance or confidence"),
        }
        model = model.view(built);
    }
    model
}

/// A method with the trading settings of a `rebalance_*` case.
macro_rules! rebalance {
    ($method:expr, $params:expr) => {{
        let params = $params;
        let mut method = $method
            .covariance(covariance_config(params))
            .current_weights(floats(&params["current_weights"]));
        if let Some(cap) = params["max_turnover"].as_f64() {
            method = method.max_turnover(cap);
        }
        if let Some(kappa) = params["turnover_penalty"].as_f64() {
            method = method.turnover_penalty(kappa);
        }
        if params["long_short"].as_bool() == Some(true) {
            method = method.allow_short();
        } else if let Some(bounds) = weight_bounds(params) {
            method = method.bounds(bounds);
        }
        method
    }};
}

fn rebalance_mean_variance(params: &Value) -> MeanVariance {
    let objective = match params["target_return"].as_f64() {
        Some(target) => MeanVariance::target_return(target),
        None => MeanVariance::risk_aversion(params["risk_aversion"].as_f64().unwrap()),
    };
    let mut method = rebalance!(objective, params);
    if params["expected_returns"].is_array() {
        method = method.expected_returns(floats(&params["expected_returns"]));
    }
    match &params["transaction_costs"] {
        Value::Array(_) => method.transaction_costs_per_asset(floats(&params["transaction_costs"])),
        cost => match cost.as_f64() {
            Some(cost) => method.transaction_costs(cost),
            None => method,
        },
    }
}

fn min_cvar(params: &Value) -> MinCvar {
    let mut method = MinCvar::default();
    if let Some(beta) = params["confidence"].as_f64() {
        method = method.confidence(beta);
    }
    if let Some(bounds) = weight_bounds(params) {
        method = method.bounds(bounds);
    }
    if let Some(target) = params["target_return"].as_f64() {
        method = method.target_return(target);
    }
    method
}

const METHODS: [&str; 17] = [
    "equal_weight",
    "inverse_volatility",
    "inverse_variance",
    "min_variance",
    "long_only_min_variance",
    "long_only_mean_variance",
    "mean_variance",
    "max_sharpe",
    "long_only_max_sharpe",
    "max_diversification",
    "risk_parity",
    "hrp",
    "herc",
    "black_litterman",
    "rebalance_min_variance",
    "rebalance_mean_variance",
    "min_cvar",
];

fn run(allocator: &Returns, method: &str, params: &Value) -> Result<Weights, CutupError> {
    match method {
        "equal_weight" => allocator.allocate(&EqualWeight),
        "inverse_volatility" => allocator.allocate(&InverseVolatility),
        "inverse_variance" => allocator.allocate(&InverseVariance),
        "min_variance" => allocator.allocate(
            &MinVariance::default()
                .allow_short()
                .covariance(covariance_config(params)),
        ),
        "long_only_min_variance" => match weight_bounds(params) {
            Some(bounds) => allocator.allocate(
                &MinVariance::default()
                    .covariance(covariance_config(params))
                    .bounds(bounds),
            ),
            None => {
                allocator.allocate(&MinVariance::default().covariance(covariance_config(params)))
            }
        },
        "long_only_mean_variance" => match weight_bounds(params) {
            Some(bounds) => allocator.allocate(&mean_variance(params).bounds(bounds)),
            None => allocator.allocate(&mean_variance(params)),
        },
        "mean_variance" => allocator.allocate(&mean_variance(params).allow_short()),
        "max_sharpe" => allocator.allocate(&max_sharpe(params).allow_short()),
        "long_only_max_sharpe" => allocator.allocate(&max_sharpe(params)),
        "max_diversification" => {
            allocator.allocate(&MaxDiversification::default().covariance(covariance_config(params)))
        }
        "risk_parity" => allocator.allocate(&risk_parity(params)),
        "hrp" => allocator.allocate(&hrp(params)),
        "herc" => allocator.allocate(&herc(params)),
        "rebalance_min_variance" => allocator.allocate(&rebalance!(MinVariance::default(), params)),
        "rebalance_mean_variance" => allocator.allocate(&rebalance_mean_variance(params)),
        "min_cvar" => allocator.allocate(&min_cvar(params)),
        "black_litterman" => black_litterman(params)
            .expected_returns(allocator)
            .map(Weights::from),
        other => unreachable!("unknown method {other} is rejected in check"),
    }
}

/// Compares one case, returning a description of the mismatch if there is one.
fn check(case: &Value, datasets: &Value) -> Option<String> {
    let dataset = case["dataset"].as_str().unwrap_or_default();
    let method = case["method"].as_str().unwrap_or_default();
    let params = &case["params"];
    let label = match params {
        Value::Null => format!("{dataset} / {method}"),
        _ => format!("{dataset} / {method} {params}"),
    };

    // Report a malformed case like any other failure instead of panicking, so the rest
    // of the cases still run.
    if datasets[dataset].is_null() {
        return Some(format!("{label}: no dataset named {dataset:?}"));
    }
    if !METHODS.contains(&method) {
        return Some(format!("{label}: unknown method {method:?}"));
    }
    if case["weights"].is_array() == case["error"].is_string() {
        return Some(format!(
            "{label}: case needs exactly one of weights or error"
        ));
    }
    let allocator = allocator(&datasets[dataset]);
    let result = run(&allocator, method, params);

    match (result, case["error"].as_str()) {
        (Err(error), Some(expected)) if format!("{error:?}").starts_with(expected) => None,
        (Err(error), Some(expected)) => {
            Some(format!("{label}: expected {expected}, got {error:?}"))
        }
        (Ok(weights), Some(expected)) => Some(format!(
            "{label}: expected {expected}, got weights {:?}",
            weights.as_slice()
        )),
        (Err(error), None) => Some(format!("{label}: unexpected error {error:?}")),
        // The min CVaR portfolio needn't be unique, so it's the CVaR that's compared. The
        // reference's weights come from HiGHS, within about 1e-10 of the returns' scale of the
        // optimum, so cutup's exact vertex must be no worse, and no more than 1e-9 better.
        (Ok(weights), None) if method == "min_cvar" => {
            let beta = params["confidence"].as_f64().unwrap_or(0.95);
            let got = allocator.cvar(&weights, beta).unwrap();
            let want = case["cvar"].as_f64().unwrap();
            let scale = returns_scale(&datasets[dataset]);
            (got > want + 1e-12 * scale || got < want - 1e-9 * scale)
                .then(|| format!("{label}: CVaR {got:e}, reference {want:e}"))
        }
        (Ok(weights), None) => {
            let expected = floats(&case["weights"]);
            let tolerance = case["tolerance"].as_f64().unwrap();
            if weights.len() != expected.len() {
                return Some(format!(
                    "{label}: {} weights, expected {}",
                    weights.len(),
                    expected.len()
                ));
            }
            // Relative to the weight's size, so large long-short weights get a fair tolerance.
            // f64::max would skip a NaN, so a non-finite weight counts as infinitely far off.
            let worst = weights
                .iter()
                .zip(&expected)
                .map(|(got, want)| (got - want).abs() / want.abs().max(1.0))
                .map(|error| if error.is_nan() { f64::INFINITY } else { error })
                .fold(0.0, f64::max);
            (worst > tolerance).then(|| {
                format!(
                    "{label}: off by {worst:.2e} (tolerance {tolerance:.0e})\n    got      {:?}\n    expected {expected:?}",
                    weights.as_slice()
                )
            })
        }
    }
}

#[test]
fn matches_python_reference() {
    let datasets: Value = serde_json::from_str(DATASETS).unwrap();
    let expected: Value = serde_json::from_str(EXPECTED).unwrap();
    let cases = expected["cases"].as_array().unwrap();
    assert!(!cases.is_empty());

    let failures: Vec<String> = cases
        .iter()
        .filter_map(|case| check(case, &datasets))
        .collect();
    assert!(
        failures.is_empty(),
        "{} of {} reference cases failed (generated with {}):\n{}",
        failures.len(),
        cases.len(),
        expected["generated_with"],
        failures.join("\n")
    );
}

#[test]
fn every_method_and_dataset_is_covered() {
    let datasets: Value = serde_json::from_str(DATASETS).unwrap();
    let expected: Value = serde_json::from_str(EXPECTED).unwrap();
    let cases = expected["cases"].as_array().unwrap();

    for method in METHODS {
        assert!(
            cases.iter().any(|case| case["method"] == method),
            "no reference case for {method}"
        );
    }
    for name in datasets.as_object().unwrap().keys() {
        assert!(
            cases.iter().any(|case| case["dataset"] == name.as_str()),
            "dataset {name} is never used"
        );
    }
}
